contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit an amount (amount > 0 allowed) and then call withdrawAll.
    // We assert that if withdrawAll does not revert, the caller's credit (observable via calling deposit then checking by attempting another withdraw) is zero
    // and address(c).balance did not increase as a result of withdrawAll (i.e., it decreased by at most amount).
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // record balance of contract before any calls
        uint before = address(c).balance;

        // perform deposit on c sending 'amount' wei
        c.deposit{value: amount}();

        // now call withdrawAll and detect revert
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule:
        // If withdrawAll succeeded then (a) the contract's balance did not increase (after <= before + amount),
        // and (b) the observable effect is that the contract's balance is at most before (i.e., withdraw sent funds out)
        // and that the caller's credit cannot still be positive as we can infer by a second withdrawAll attempt not sending more than before change.
        // To make an observable assertion without direct getter for credit, we assert that after a successful withdrawAll,
        // performing another withdrawAll cannot further decrease address(c).balance (it may revert or do nothing).

        if (!reverted) {
            // withdrawAll should not increase c's balance
            // and a second withdrawAll should not further decrease the balance
            bool secondReverted;
            uint mid = address(c).balance;
            try c.withdrawAll() {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            uint postSecond = address(c).balance;

            assert(postSecond >= mid && postSecond <= before + amount);
        } else {
            // If first withdrawAll reverted, no further guarantees about balances; still assert that c's balance did not increase above before+amount due to our deposit
            assert(address(c).balance <= before + amount);
        }
    }

    receive() external payable {}
}

