contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount of wei to deposit into c
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeTestBalance = address(this).balance;
        uint beforeCBalance = address(c).balance;

        // perform deposit to c
        c.deposit{value: depositAmount}();

        // record balances after deposit
        uint afterDepositTestBalance = address(this).balance;
        uint afterDepositCBalance = address(c).balance;

        // now try withdrawAll and capture whether it reverted
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // read observable public data: c has no public getter for credit or balance
        // but address(c).balance is observable. However credit mapping is not public,
        // so we cannot read it. We can instead reason about net Ether movement.

        // Construct the general invariant:
        // If withdraw succeeded then test contract balance increased by depositAmount
        // and c.balance decreased by depositAmount.
        // If withdraw reverted then c's balance is at least afterDepositCBalance (no loss),
        // and the test contract did not gain ether beyond what it had right after deposit.

        if (withdrew) {
            assert(address(this).balance == afterDepositTestBalance + depositAmount &&
                   address(c).balance + depositAmount == afterDepositCBalance);
        } else {
            assert(address(this).balance == afterDepositTestBalance &&
                   address(c).balance >= afterDepositCBalance);
        }
    }

    receive() external payable {}
}

