contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs: deposit(amount) from this contract, then attempt withdrawAll(),
    // and asserts the invariant described in property_summary.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record balances before any operations
        uint beforeC = address(c).balance;

        // make a deposit of `amount` into c (this will increase c's recorded credit for this contract)
        c.deposit{value: amount}();

        // read recorded credit after deposit via the public mapping getter
        uint creditAfterDeposit = c.credit(address(this));

        // verify that the recorded credit equals at least the deposited amount (mapping accumulates)
        // We don't assert here; just proceed to attempt withdrawAll and capture revert status.

        bool reverted;
        // try calling withdrawAll and catch revert
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint creditAfter = c.credit(address(this));

        // General rule (single assert):
        // If withdrawAll did NOT revert, then C's balance decreased by exactly creditAfterDeposit
        // and the recorded credit for this contract is zero.
        // If withdrawAll DID revert, then C's balance did not decrease and the recorded credit remains creditAfterDeposit.
        assert(
            (!reverted && beforeC + amount >= beforeC && // trivial guard to keep expression non-constant across inputs
                afterC + creditAfterDeposit == beforeC + amount && creditAfter == 0)
            ||
            (reverted && afterC == beforeC + amount && creditAfter == creditAfterDeposit)
        );
    }

    receive() external payable {}
}

