    constructor(C _c) { c = _c; }

    // depositAmount is sent from this contract to C via deposit, then we call withdrawAll.
    // We cannot read the internal credit mapping, so we reason only about observable balances and revert behavior.
    function run(uint depositAmount) public payable {
        // ensure this contract has enough Ether to deposit
        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint myBalBefore = address(this).balance;
        uint cBalBefore = address(c).balance;

        // perform deposit into C
        c.deposit{value: depositAmount}();

        // record balances after deposit and before withdraw
        uint myBalAfterDeposit = address(this).balance;
        uint cBalAfterDeposit = address(c).balance;

        // deposit should move exactly depositAmount from this contract to C (observable)
        // (we don't assert that here; it's part of allowed behaviors but not necessary)

        bool reverted;
        // attempt withdrawAll and capture whether it reverts
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // balances after withdraw attempt
        uint myBalFinal = address(this).balance;
        uint cBalFinal = address(c).balance;

        // General rule:
        // If withdrawAll returned (did not revert), then the change in C's balance is at most the amount we deposited,
        // and the change in this contract's balance is at most the amount we deposited. If it reverted, no guarantees here.
        // This avoids needing access to the internal credit mapping while capturing that withdrawAll cannot siphon more
        // than the caller had deposited in this single-depositor scenario.
        assert(reverted || (cBalBefore - cBalFinal <= depositAmount && myBalFinal - myBalBefore <= depositAmount));
    }

    // accept ether if sent back
    receive() external payable {}
}

